import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Data sources","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sources.md","filePath":"guide/sources.md","lastUpdated":1791997268000}'),s={name:"guide/sources.md"};function n(i,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="data-sources" tabindex="-1">Data sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data sources&quot;">​</a></h1><p>Choose an index that fits your research. Coverage, metadata, access, and filters vary across providers.</p><h2 id="source-directory" tabindex="-1">Source directory <a class="header-anchor" href="#source-directory" aria-label="Permalink to &quot;Source directory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Community</th><th>Online BYOK</th><th>Focus</th></tr></thead><tbody><tr><td><a href="https://openalex.org/" target="_blank" rel="noreferrer">OpenAlex</a></td><td>Key recommended</td><td>Key required</td><td>Broad discovery and citation expansion</td></tr><tr><td><a href="https://arxiv.org/" target="_blank" rel="noreferrer">arXiv</a></td><td>No key</td><td>No key</td><td>Scientific preprints</td></tr><tr><td><a href="https://www.crossref.org/" target="_blank" rel="noreferrer">Crossref</a></td><td>No key</td><td>No key</td><td>DOI and publication metadata</td></tr><tr><td><a href="https://www.semanticscholar.org/" target="_blank" rel="noreferrer">Semantic Scholar</a></td><td>Optional key</td><td>Key required</td><td>Papers and scholarly graph metadata</td></tr><tr><td><a href="https://pubmed.ncbi.nlm.nih.gov/" target="_blank" rel="noreferrer">PubMed</a></td><td>Optional NCBI key</td><td>Key required</td><td>Biomedical and life-science research</td></tr><tr><td>Google Scholar via <a href="https://serper.dev/" target="_blank" rel="noreferrer">Serper</a></td><td>Serper key required</td><td>Key required</td><td>Scholar results through the supported API</td></tr><tr><td>PaperHub top CS conferences</td><td>No key</td><td>No key</td><td>PaperHub&#39;s conference collection</td></tr><tr><td><a href="https://developer.clarivate.com/apis/wos-starter" target="_blank" rel="noreferrer">Web of Science Starter</a></td><td>Clarivate key required</td><td>Key required</td><td>Supported WoS collection when enabled</td></tr></tbody></table><p>PaperSeek Service manages source access for you. Community permits anonymous access or optional keys as shown above. Online BYOK has a separate access policy: add and save source keys in Settings for every source that takes a key, including OpenAlex, PubMed, and Semantic Scholar. arXiv, Crossref, and PaperHub need no key. A model key is not a data-source key.</p><h2 id="configure-and-test-a-source" tabindex="-1">Configure and test a source <a class="header-anchor" href="#configure-and-test-a-source" aria-label="Permalink to &quot;Configure and test a source&quot;">​</a></h2><p>Open <strong>Settings → Data sources</strong> and choose <strong>Configure</strong> or <strong>Configure key</strong> on the source row. Enter the key and options, then click <strong>Save</strong>.</p><p><strong>Test connection</strong> inside this dialog also saves the current key and options before testing. If saving fails, the test does not start. Once saving succeeds, a failed test or subsequently cancelling the dialog does not undo it; reopen the source configuration to change or clear the saved key. The table&#39;s <strong>Test</strong> and <strong>Test all</strong> use the configured credentials without saving a form draft. Model connection draft tests do not save; see <a href="./models">models and ranking</a>.</p><h2 id="obtain-credentials" tabindex="-1">Obtain credentials <a class="header-anchor" href="#obtain-credentials" aria-label="Permalink to &quot;Obtain credentials&quot;">​</a></h2><ul><li><a href="https://openalex.org/settings/api" target="_blank" rel="noreferrer">OpenAlex API settings</a>.</li><li><a href="https://www.semanticscholar.org/product/api#api-key-form" target="_blank" rel="noreferrer">Semantic Scholar key request</a>.</li><li><a href="https://www.ncbi.nlm.nih.gov/books/NBK25497/" target="_blank" rel="noreferrer">NCBI API guidance</a>.</li><li><a href="https://serper.dev/" target="_blank" rel="noreferrer">Serper account</a>.</li><li><a href="https://developer.clarivate.com/apis/wos-starter" target="_blank" rel="noreferrer">WoS Starter application</a>.</li></ul><p>Provider subscriptions and rate limits are separate from PaperSeek accounts and credits.</p><h2 id="fields-and-categories" tabindex="-1">Fields and categories <a class="header-anchor" href="#fields-and-categories" aria-label="Permalink to &quot;Fields and categories&quot;">​</a></h2><p>OpenAlex uses supported discipline options; its semantic lane applies supported filtering behavior. arXiv uses categories. WoS categories and the WoS database selector are separate. Other sources use textual field guidance.</p><p>Restricting a field can exclude interdisciplinary work. Start without it unless your research design requires the constraint.</p><h2 id="missing-metadata" tabindex="-1">Missing metadata <a class="header-anchor" href="#missing-metadata" aria-label="Permalink to &quot;Missing metadata&quot;">​</a></h2><p>Records can lack abstracts, years, citation counts, or open PDF links. Missing metadata is not a quality judgment.</p><p>Version 1.0.0-beta2 has no separate cross-source abstract-filling or citation-count enrichment switch. Choose informative abstracts for review writing.</p><h2 id="multiple-keys" tabindex="-1">Multiple keys <a class="header-anchor" href="#multiple-keys" aria-label="Permalink to &quot;Multiple keys&quot;">​</a></h2><p>OpenAlex and Serper support key pools separated by whitespace, commas, or semicolons. Requests rotate the starting key; authentication failures are handled separately from transient errors.</p><p>Rotation does not change provider terms or guarantee remaining credit. See <a href="./../reference/configuration">configuration</a>.</p>',20)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
